    for (char ch : line) {
        if (ch == '(') {
            if (!currentPart.empty()) {
                splitParts.push_back(currentPart);
                currentPart.clear();
            }
            inside = true;
        } else if (ch == ')') {
            if (!currentPart.empty()) {
                splitParts.push_back(currentPart);
                currentPart.clear();
            }
            inside = false;
        } else {
            currentPart += ch;
        }
    }
    if (!currentPart.empty()) {
